namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string InstructorName { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = "";
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    List<Department> GetDepartments();
    Department? GetDepartment(int id);
    List<Course> GetCourses(string? search = null, int? departmentId = null);
    Course? GetCourse(int id);
    List<Course> GetFeaturedCourses();
    void SubmitEnrollmentRequest(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language arts." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Title = "Introduction to Programming", Code = "CS 101", Description = "Fundamentals of programming using Python. Covers variables, control structures, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00-9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has authored two textbooks on Python programming.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", Code = "CS 201", Description = "Study of fundamental data structures including arrays, linked lists, trees, and graphs. Analysis of algorithm efficiency.", Credits = 4, Schedule = "TTh 10:30-11:50 AM", InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez specializes in algorithm design and has published extensively on graph algorithms.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
            new() { Id = 3, Title = "Database Systems", Code = "CS 305", Description = "Design and implementation of relational databases. SQL, normalization, transaction processing, and query optimization.", Credits = 3, Schedule = "MWF 1:00-1:50 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked as a database architect at Oracle for 10 years before joining academia.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },

            // Mathematics
            new() { Id = 4, Title = "Calculus I", Code = "MATH 151", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "MWF 8:00-8:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator known for making calculus accessible to all students.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
            new() { Id = 5, Title = "Linear Algebra", Code = "MATH 220", Description = "Vector spaces, linear transformations, matrices, determinants, and eigenvalues.", Credits = 3, Schedule = "TTh 9:00-10:20 AM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson's research focuses on applications of linear algebra in machine learning.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 6, Title = "Probability and Statistics", Code = "MATH 340", Description = "Introduction to probability theory, random variables, distributions, and statistical inference.", Credits = 3, Schedule = "MWF 11:00-11:50 AM", InstructorName = "Dr. Alan Patel", InstructorBio = "Dr. Patel has consulted for major tech companies on statistical modeling and data analysis.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },

            // Physics
            new() { Id = 7, Title = "General Physics I", Code = "PHYS 101", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.", Credits = 4, Schedule = "TTh 1:00-2:20 PM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is a former NASA researcher with a passion for teaching fundamental physics.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true },
            new() { Id = 8, Title = "Electromagnetism", Code = "PHYS 202", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "MWF 10:00-10:50 AM", InstructorName = "Dr. Lisa Chang", InstructorBio = "Dr. Chang's research in electromagnetic theory has been published in Nature Physics.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 9, Title = "Quantum Mechanics", Code = "PHYS 401", Description = "Wave-particle duality, Schrodinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "TTh 3:00-4:20 PM", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park has contributed to quantum computing research at IBM and MIT.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },

            // English
            new() { Id = 10, Title = "College Writing", Code = "ENG 101", Description = "Development of academic writing skills including argumentation, research methods, and critical analysis.", Credits = 3, Schedule = "MWF 9:00-9:50 AM", InstructorName = "Prof. Jennifer Adams", InstructorBio = "Prof. Adams is a published author and writing workshop leader with 20 years of teaching experience.", DepartmentId = 4, DepartmentName = "English", IsFeatured = true },
            new() { Id = 11, Title = "American Literature", Code = "ENG 250", Description = "Survey of American literature from colonial period to present. Focus on major authors and literary movements.", Credits = 3, Schedule = "TTh 11:00 AM-12:20 PM", InstructorName = "Dr. Thomas Wright", InstructorBio = "Dr. Wright specializes in 20th-century American fiction and has written for The Atlantic.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
            new() { Id = 12, Title = "Creative Writing", Code = "ENG 310", Description = "Workshop-based course in fiction and poetry writing. Students produce a portfolio of original work.", Credits = 3, Schedule = "MW 2:00-3:20 PM", InstructorName = "Prof. Rachel Green", InstructorBio = "Prof. Green is a novelist whose debut won the National Book Award for Fiction.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollmentRequests.Add(request);
    }
}

